using Radiacode.Core;

namespace Radiacode.Core.Tests;

/// <summary>Real DATA_BUF frames captured from an RC-110 on firmware 4.15 (16-byte real-time records).</summary>
public class FirmwareFrameTests
{
    private static readonly DateTime Base = new(2026, 11, 11, 10, 0, 0);

    [Fact]
    public void RealTime16Byte_DoesNotTruncateFollowingRecords()
    {
        var recs = Decoders.DecodeDataBuf(new ByteReader(Convert.FromHexString("3F00004DD3FFFFBC780441CB649D362D00960040200000400101EEFFFFFF0200320000000000604199BB16370000804011C7BA36")), Base);
        var rt = Assert.IsType<RealTimeData>(Assert.Single(recs));
        Assert.InRange(rt.CountRate, 8.0, 9.0);
    }

    [Fact]
    public void Backlog_ContainsRareData_WithDoseBatteryTemperature()
    {
        var recs = Decoders.DecodeDataBuf(new ByteReader(Convert.FromHexString("")), Base);
        var rare = Assert.Single(recs.OfType<RareData>());
        Assert.InRange(rare.DoseMicroSv, 7.0, 8.0);
        Assert.InRange(rare.TemperatureC, 24.0, 24.6);
        Assert.InRange(rare.ChargePercent, 99.0, 100.0);
        Assert.Single(recs.OfType<DoseRateDb>());
    }

    [Theory]
    [InlineData((ushort)0x0040, false)]
    [InlineData((ushort)0x4040, true)]   // captured while on USB power, FW 4.15
    public void ChargingBit(ushort flags, bool charging) =>
        Assert.Equal(charging, new RealTimeData(Base, 8.5f, 4.4f, 0.005f, 15f, flags, 0).IsCharging);
}